import pytest

from sales_dashboard.loader import daily_conversion_counts, dedupe_sessions, parse_session_log
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def test_conversion_rate_basic():
    assert conversion_rate([{"converted": True}, {"converted": False}]) == 0.5


def test_pooled_conversion_rate_equal_groups():
    groups = {"a": [{"converted": True}, {"converted": False}], "b": [{"converted": True}, {"converted": False}]}
    assert pooled_conversion_rate(groups) == 0.5


def test_parse_session_log_one_line():
    assert parse_session_log(["x1,3,1"]) == [{"id": "x1", "day": 3, "converted": True}]


def test_campaign_summary_basic():
    e = [{"id": "a", "day": 1, "converted": True}, {"id": "b", "day": 2, "converted": False}]
    assert campaign_summary({"g": e}, 1)["groups"] == 1


def test_conversion_rate_includes_none_in_denominator():
    assert conversion_rate([{"converted": True}, {"converted": None}]) == 0.5
    assert conversion_rate([{"converted": None}]) == 0.0


def test_conversion_rate_empty():
    assert conversion_rate([]) == 0.0


def test_pooled_conversion_rate_weights_sessions_not_groups():
    groups = {
        "a": [{"converted": True}],
        "b": [{"converted": False}, {"converted": None}],
        "empty": [],
    }
    assert pooled_conversion_rate(groups) == 1 / 3


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_pooled_conversion_rate_without_sessions(groups):
    assert pooled_conversion_rate(groups) == 0.0


@pytest.mark.parametrize("days, expected", [(0, 0), (2, 7), (10, 8)])
def test_conversions_in_window(days, expected):
    assert conversions_in_window([1, 3, 4], days) == expected


def test_parse_session_log_skips_blank_lines_and_comments_and_maps_flags():
    lines = ["", " \t\n", "  # comment", " x , 3 , 1 ", "y,4,0", "z,5,  "]
    assert parse_session_log(lines) == [
        {"id": "x", "day": 3, "converted": True},
        {"id": "y", "day": 4, "converted": False},
        {"id": "z", "day": 5, "converted": None},
    ]


@pytest.mark.parametrize("bad_line", ["x,3", "x,3,1,extra", "x,not-a-day,1"])
def test_parse_session_log_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"\bline 4\b"):
        parse_session_log(["# comment", "", "ok,1,1", bad_line])


def test_dedupe_sessions_keeps_last_record_per_id_and_sorts():
    earlier = {"id": "b", "day": 4, "converted": True}
    latest = {"id": "b", "day": 2, "converted": False}
    same_day = {"id": "a", "day": 2, "converted": True}
    next_day = {"id": "c", "day": 3, "converted": True}
    assert dedupe_sessions([next_day, earlier, latest, same_day]) == [same_day, latest, next_day]


def test_daily_conversion_counts_includes_all_days_in_range():
    events = [
        {"day": 0, "converted": True},
        {"day": 1, "converted": True},
        {"day": 1, "converted": True},
        {"day": 2, "converted": None},
        {"day": 3, "converted": True},
        {"day": 3, "converted": False},
        {"day": 4, "converted": True},
    ]
    assert daily_conversion_counts(events, 1, 3) == [2, 0, 1]
    assert daily_conversion_counts(events, 3, 1) == []


def test_campaign_summary_uses_calendar_days_and_nonempty_groups():
    groups = {
        "early": [{"day": 1, "converted": True}],
        "late": [{"day": 4, "converted": True}, {"day": 5, "converted": False}],
        "empty": [],
    }
    assert campaign_summary(groups, 3) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert campaign_summary({"empty": []}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_converting_groups_breaks_ties_by_name_and_excludes_empty_groups():
    groups = {
        "z": [{"converted": True}],
        "b": [{"converted": False}],
        "a": [{"converted": True}],
        "empty": [],
    }
    assert top_converting_groups(groups, 2) == ["a", "z"]
    assert top_converting_groups(groups, 5) == ["a", "z", "b"]


def test_conversion_rate_by_group_sorts_names_and_preserves_empty_groups():
    groups = {"z": [{"converted": True}], "b": [{"converted": None}], "a": []}
    rates = conversion_rate_by_group(groups)
    assert rates == {"a": None, "b": 0.0, "z": 1.0}
    assert list(rates) == ["a", "b", "z"]


@pytest.mark.parametrize("counts, expected", [([], 0), ([0, -1], 0), ([1, 0, 2, 3, -1, 4], 2)])
def test_longest_conversion_streak_counts_only_consecutive_positive_entries(counts, expected):
    assert longest_conversion_streak(counts) == expected

