"""Product analytics dashboard: conversion statistics over customer sessions."""


_CONVERTED_FLAGS = {"1": True, "0": False, "": None}


def parse_session_log(lines):
    """Parse log lines into sessions. See SPEC.md section 4."""
    out = []
    for number, line in enumerate(lines, start=1):
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        fields = [field.strip() for field in line.split(",")]
        if len(fields) != 3:
            raise ValueError(f"line {number}: expected exactly three fields")
        id_, day, flag = fields
        try:
            day = int(day)
        except ValueError as exc:
            raise ValueError(f"line {number}: day must be an integer") from exc
        if flag not in _CONVERTED_FLAGS:
            raise ValueError(f"line {number}: converted must be 1, 0, or empty")
        out.append({"id": id_, "day": day, "converted": _CONVERTED_FLAGS[flag]})
    return out


def dedupe_sessions(events):
    """Remove duplicate sessions. See SPEC.md section 5."""
    latest = {event["id"]: event for event in events}
    return sorted(latest.values(), key=lambda e: (e["day"], e["id"]))


def daily_conversion_counts(events, start_day, end_day):
    """Daily counts of converted sessions. See SPEC.md section 6."""
    counts = [0] * (end_day - start_day + 1)
    for event in events:
        day = event["day"]
        if start_day <= day <= end_day and event["converted"] is True:
            counts[day - start_day] += 1
    return counts
